From 4e874d308e839f810abf1cf1e1fa7f60e7ac86fd Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:29:23 +0100
Subject: [PATCH] solid-device-automounter: let the session wait for login
 automounts

Disks set to mount on login were mounted alongside plasmashell and
autostarted apps, so files on them were missing at startup. Add a D-Bus
call that returns once those mounts finish, and a unit to order on it.

BUG: 323151
---
 solid-device-automounter/kded/CMakeLists.txt  |  2 ++
 .../kded/DeviceAutomounter.cpp                | 35 +++++++++++++++++++
 .../kded/DeviceAutomounter.h                  | 15 +++++++-
 .../plasma-device-automounter-wait.service    | 10 ++++++
 4 files changed, 61 insertions(+), 1 deletion(-)
 create mode 100644 solid-device-automounter/kded/plasma-device-automounter-wait.service

diff --git a/solid-device-automounter/kded/CMakeLists.txt b/solid-device-automounter/kded/CMakeLists.txt
index c1db10be2e..0e3b3ba09c 100644
--- a/solid-device-automounter/kded/CMakeLists.txt
+++ b/solid-device-automounter/kded/CMakeLists.txt
@@ -8,3 +8,5 @@ kconfig_add_kcfg_files(kded_device_automounter_SRCS
 kcoreaddons_add_plugin(kded_device_automounter SOURCES ${device_automounter_lib_SRCS} ${kded_device_automounter_SRCS} INSTALL_NAMESPACE kf6/kded)
 set_target_properties(kded_device_automounter PROPERTIES OUTPUT_NAME device_automounter)
 target_link_libraries(kded_device_automounter Qt::DBus KF6::CoreAddons KF6::Service KF6::ConfigCore KF6::ConfigGui KF6::DBusAddons KF6::Solid)
+
+install(FILES plasma-device-automounter-wait.service DESTINATION ${KDE_INSTALL_SYSTEMDUSERUNITDIR})
diff --git a/solid-device-automounter/kded/DeviceAutomounter.cpp b/solid-device-automounter/kded/DeviceAutomounter.cpp
index d258cff8c4..7512e9107c 100644
--- a/solid-device-automounter/kded/DeviceAutomounter.cpp
+++ b/solid-device-automounter/kded/DeviceAutomounter.cpp
@@ -50,6 +50,7 @@ void DeviceAutomounter::init()
                                              QStringLiteral("unloadModule"));
         msg.setArguments({QVariant(QStringLiteral("device_automounter"))});
         dbus.call(msg, QDBus::NoBlock);
+        loginMountDone(QString());
         return;
     }

@@ -63,6 +64,29 @@ void DeviceAutomounter::init()
         automountDevice(volume, m_settings->Login);
     }
     m_settings->save();
+    loginMountDone(QString());
+}
+
+void DeviceAutomounter::waitForLoginMounts()
+{
+    if (m_loginMountsDone) {
+        return;
+    }
+    setDelayedReply(true);
+    m_loginMountWaiters.append(message());
+}
+
+void DeviceAutomounter::loginMountDone(const QString &udi)
+{
+    m_pendingLoginMounts.remove(udi);
+    if (m_loginMountsDone || !m_pendingLoginMounts.isEmpty()) {
+        return;
+    }
+    m_loginMountsDone = true;
+    for (const QDBusMessage &waiter : std::as_const(m_loginMountWaiters)) {
+        QDBusConnection::sessionBus().send(waiter.createReply());
+    }
+    m_loginMountWaiters.clear();
 }

 void DeviceAutomounter::deviceMountChanged(bool accessible, const QString &udi)
@@ -83,6 +107,17 @@ void DeviceAutomounter::automountDevice(Solid::Device &dev, AutomounterSettings:
         if (m_settings->shouldAutomountDevice(dev.udi(), type)) {
             Solid::StorageVolume *sv = dev.as<Solid::StorageVolume>();
             if (!sa->isAccessible() && !sv->isIgnored()) {
+                if (type == AutomounterSettings::Login) {
+                    m_pendingLoginMounts.insert(dev.udi());
+                    connect(
+                        sa,
+                        &Solid::StorageAccess::setupDone,
+                        this,
+                        [this](Solid::ErrorType, const QVariant &, const QString &udi) {
+                            loginMountDone(udi);
+                        },
+                        Qt::SingleShotConnection);
+                }
                 sa->setup();
             }
         }
diff --git a/solid-device-automounter/kded/DeviceAutomounter.h b/solid-device-automounter/kded/DeviceAutomounter.h
index 5f5096ae2b..f778684346 100644
--- a/solid-device-automounter/kded/DeviceAutomounter.h
+++ b/solid-device-automounter/kded/DeviceAutomounter.h
@@ -9,13 +9,22 @@
 #include <KDEDModule>
 #include <Solid/Device>

-class DeviceAutomounter : public KDEDModule
+#include <QDBusContext>
+#include <QDBusMessage>
+#include <QSet>
+
+class DeviceAutomounter : public KDEDModule, protected QDBusContext
 {
     Q_OBJECT
+    Q_CLASSINFO("D-Bus Interface", "org.kde.DeviceAutomounter")
 public:
     explicit DeviceAutomounter(QObject *parent = nullptr, const QVariantList &args = QVariantList());
     ~DeviceAutomounter() override;

+public Q_SLOTS:
+    // Returns once the devices to be mounted on login have finished mounting
+    Q_SCRIPTABLE void waitForLoginMounts();
+
 private Q_SLOTS:
     void init();
     void deviceAdded(const QString &udi);
@@ -23,6 +32,10 @@ private Q_SLOTS:

 private:
     void automountDevice(Solid::Device &dev, AutomounterSettings::AutomountType type);
+    void loginMountDone(const QString &udi);

     AutomounterSettings *m_settings;
+    QSet<QString> m_pendingLoginMounts;
+    bool m_loginMountsDone = false;
+    QList<QDBusMessage> m_loginMountWaiters;
 };
diff --git a/solid-device-automounter/kded/plasma-device-automounter-wait.service b/solid-device-automounter/kded/plasma-device-automounter-wait.service
new file mode 100644
index 0000000000..71ef019cbe
--- /dev/null
+++ b/solid-device-automounter/kded/plasma-device-automounter-wait.service
@@ -0,0 +1,10 @@
+[Unit]
+Description=Wait for removable devices to be mounted on login
+After=plasma-kded6.service
+Before=plasma-plasmashell.service xdg-desktop-autostart.target
+PartOf=graphical-session.target
+
+[Service]
+Type=oneshot
+ExecStart=-busctl --user --timeout=10 call org.kde.kded6 /modules/device_automounter org.kde.DeviceAutomounter waitForLoginMounts
+Slice=session.slice
-- 
